//! `http-state`'s `tests/data/parser.json`: the cookie parser corpus (the
//! RFC 6265 interoperability tests, `tests/data/parser/*-test` and
//! `*-expected`, collected into one file by the repository's
//! `tools/test_data_to_json`), as a table of cases.
//!
//! Each row has a `test` name, the `Set-Cookie` header values the server
//! `received` in one response to `http://home.example.org:8888/cookie-parser?<test>`,
//! the `sent` cookies the user agent must then send, as `{name, value}`
//! pairs, to `/cookie-parser-result?<test>` on the same server, or, when
//! the row has a `sent-to`, to that URL instead (a path on the same
//! server, or an absolute URL: the test's `Location` header).

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["parser.json"];

fn bytes(s: &str) -> String {
    let v: Vec<String> = s.bytes().map(|b| format!("0x{b:02X}")).collect();
    format!("&[{}]", v.join(", "))
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let text = std::fs::read_to_string(dir.join("parser.json"))
        .map_err(|e| format!("parser.json: {e}"))?;
    let rows: Value = serde_json::from_str(&text).map_err(|e| format!("parser.json: {e}"))?;
    let rows = rows
        .as_array()
        .ok_or_else(|| "parser.json: not a JSON array".to_owned())?;
    let mut out = String::new();
    out.push_str("// @generated by `cargo xtask testdata` from tests/data/http-state-parser/.\n");
    out.push_str("// Do not edit: `cargo xtask verify` fails if this differs from what the\n");
    out.push_str("// converter (xtask/src/testdata/http_state_parser.rs) produces.\n");
    out.push_str("// Source, commit and license: tests/data/http-state-parser/SOURCE.md.\n");
    out.push_str("const PARSER: &[Case] = &[\n");
    for (index, row) in rows.iter().enumerate() {
        let bad = |what: &str| format!("parser.json[{index}]: {what}");
        let name = row
            .get("test")
            .and_then(Value::as_str)
            .ok_or_else(|| bad("no string \"test\""))?;
        let received: Vec<String> = row
            .get("received")
            .and_then(Value::as_array)
            .ok_or_else(|| bad("no \"received\" array"))?
            .iter()
            .map(|v| {
                v.as_str()
                    .map(bytes)
                    .ok_or_else(|| bad("received is not a string"))
            })
            .collect::<Result<_, _>>()?;
        let sent_to = match row.get("sent-to") {
            None => "None".to_owned(),
            Some(Value::String(s)) => format!("Some({s:?})"),
            Some(_) => return Err(bad("sent-to is not a string")),
        };
        let sent: Vec<String> = row
            .get("sent")
            .and_then(Value::as_array)
            .ok_or_else(|| bad("no \"sent\" array"))?
            .iter()
            .map(|c| {
                let n = c.get("name").and_then(Value::as_str);
                let v = c.get("value").and_then(Value::as_str);
                match (n, v) {
                    (Some(n), Some(v)) => Ok(format!("({}, {})", bytes(n), bytes(v))),
                    _ => Err(bad("a sent cookie has no name or value")),
                }
            })
            .collect::<Result<_, _>>()?;
        writeln!(
            out,
            "    Case {{ name: {name:?}, received: &[{}], sent_to: {sent_to}, sent: &[{}] }},",
            received.join(", "),
            sent.join(", ")
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
